Here's a Python program that simulates a game of hangman:

```python
import random

# Function to draw the hangman's gallows
def draw_hangman(num_guesses):
    if num_guesses == 0:
        return "   /|\\   "
    elif num_guesses == 1:
        return "   /|\\   "
    elif num_guesses == 2:
        return "   /|\\   " + "   |   "
    elif num_guesses == 3:
        return "   /|\\   " + "   |   " + "  /   "
    elif num_guesses == 4:
        return "   /|\\   " + "   |   " + "  /   " + "   \\ "
    elif num_guesses == 5:
        return "   /|\\   " + "   |   " + "  /   " + "   \\ " + "  / "
    elif num_guesses == 6:
        return "   /|\\   " + "   |   " + "  /   " + "   \\ " + "  / " + "  | "
    elif num_guesses == 7:
        return "   /|\\   " + "   |   " + "  /   " + "   \\ " + "  / " + "  | " + "  -"
    else:
        return "   /|\\   " + "   |   " + "  /   " + "   \\ " + "  / " + "  | " + "  -" + "  /"

# Function to check if the user's guess matches the word
def check_guess(word, guess):
    return guess.lower() in word.lower()

# Function to play the game of hangman
def play_hangman():
    word = "hello"  # You can change this to any word you want
    num_guesses = 7

    while num_guesses > 0:
        print(draw_hangman(num_guesses))
        guess = input("Guess a letter: ").lower()
        if check_guess(word, guess):
            print("Correct! The letter is in the word.")
            word = word.replace(guess, "", 1)
        else:
            print("Incorrect! The gallows are drawing.")
            num_guesses -= 1

    if word == "":
        print("Congratulations! You win the game of hangman!")
    else:
        print("Sorry, you lose the game of hangman.")

# Call the play_hangman function
play_hangman()
```

This program defines functions to draw the hangman's gallows and check if the user's guess matches the word. The main function plays the game of hangman by repeatedly drawing the gallows and checking if the user's guess matches the word until the user either wins or loses.
